<div class="d-flex justify-content-between align-items-center mb-4"><div class="content-heading"><h1>Contact Messages</h1><p>Messages sent from the live storefront contact form.</p></div><a href="<?php echo e(route('admin.contact.edit')); ?>" class="btn btn-outline-secondary">Contact settings</a></div>
